from pantryline.store import Store
from pantryline.models import Ingredient
def mk(n, cat='x'):
    s = Store()
    for k in range(n):
        s.add(Ingredient(id='k%02d' % k, name='N%02d' % k, aisle=cat, qty=(k * 5) % 7, price=1.0 + k))
    return s
